// plugins/hack.js
// Demostración visual inocua para un bot Baileys.
// IMPORTANTE:
// 1. Pega el Base64 completo del audio en AUDIO_BASE64.
// 2. Baileys no ejecuta HTML/JavaScript enviado como mensaje de WhatsApp.
//    La propiedad DEMO_HTML sirve para abrir la demostración en un visor web
//    propio; el comando de abajo envía un aviso de texto al chat.

const AUDIO_BASE64 = '';

const DEMO_HTML = `<!doctype html>
<html lang="es">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Demostración visual</title>
  <style>
    body {
      margin: 0;
      padding: 24px;
      background: #050807;
      color: #00ff88;
      font: 15px/1.5 monospace;
    }
    .panel {
      max-width: 680px;
      margin: 30px auto;
      padding: 20px;
      border: 1px solid #00ff88;
      border-radius: 12px;
      background: #080d0a;
      box-shadow: 0 0 24px #00ff8822;
    }
    h1 { font-size: 22px; }
    button {
      padding: 12px 18px;
      border: 0;
      border-radius: 6px;
      background: #00ff88;
      color: #001b0d;
      font: bold 14px monospace;
      cursor: pointer;
    }
    #console {
      min-height: 120px;
      margin-top: 18px;
      padding: 12px;
      white-space: pre-wrap;
      border: 1px solid #164d32;
      background: #020403;
    }
    .muted { color: #83b99b; }
  </style>
</head>
<body>
  <main class="panel">
    <h1>MASSIVE_EXPLOIT_V9.9</h1>
    <p class="muted">DEMOSTRACIÓN VISUAL — NO REALIZA ACCIONES SOBRE SISTEMAS</p>
    <p id="status">[ SISTEMA EN ESPERA ]</p>
    <button id="start" type="button">INICIAR SIMULACIÓN</button>
    <div id="console">Esperando inicio...</div>
    <audio id="sound" loop preload="auto">
      <source src="data:audio/mpeg;base64,${AUDIO_BASE64}" type="audio/mpeg">
    </audio>
  </main>

  <script>
    (function () {
      const button = document.getElementById('start');
      const audio = document.getElementById('sound');
      const output = document.getElementById('console');
      const status = document.getElementById('status');

      button.addEventListener('click', async function () {
        if (!audio.querySelector('source').getAttribute('src').endsWith(',')) {
          try {
            await audio.play();
          } catch (error) {
            status.textContent = '[ AUDIO BLOQUEADO O NO DISPONIBLE ]';
          }
        } else {
          status.textContent = '[ FALTA CONFIGURAR EL AUDIO BASE64 ]';
        }

        status.textContent = '[ SIMULACIÓN EN EJECUCIÓN ]';
        output.textContent = [
          '[01] Iniciando demostración...',
          '[02] Comprobando interfaz...',
          '[03] Ejecutando animación visual...',
          '[04] No se han realizado accesos ni cambios reales.',
          '[05] Simulación completada.'
        ].join('\\n');

        button.disabled = true;
        button.textContent = 'SIMULACIÓN INICIADA';
      });
    })();
  </script>
</body>
</html>`;

module.exports = {
  name: 'hack',
  alias: ['massive'],
  desc: 'Envía una demostración visual inocua',

  // Puedes importar DEMO_HTML desde otro módulo/visor web si lo necesitas.
  DEMO_HTML,

  async execute(sock, msg, args, from) {
    try {
      await sock.sendMessage(
        from,
        {
          text:
            '⚡ MASSIVE EXPLOIT // DEMO\\n\\n' +
            'Demostración visual disponible en el visor web.\\n' +
            'Esta prueba es simulada y no realiza accesos ni extracción de datos.'
        },
        { quoted: msg }
      );

      console.log('[DEMO] Aviso enviado correctamente.');
    } catch (error) {
      console.error('[DEMO] Error al enviar el aviso:', error);

      await sock.sendMessage(
        from,
        { text: '❌ No se pudo enviar el aviso de demostración.' },
        { quoted: msg }
      );
    }
  }
};